/* Starbucks DNA — siren green, cream house warmth */
.theme-starbucks-dna {
  --bg: oklch(0.976 0 0);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.941 0.003 67.8);
  --fg: oklch(0.320 0.036 175.4);
  --fg-muted: oklch(0.574 0.022 176.9);
  --accent: oklch(0.482 0.107 161.2);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.735 0.146 84.3);
  --line: oklch(0.887 0.005 67.8);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.482 0.107 161.2);
  --radius: 1.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Assistant", sans-serif;
  --font-body: "Assistant", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-starbucks-dna h1,
.theme-starbucks-dna h2,
.theme-starbucks-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-starbucks-dna h1 { font-weight: 600; }
.theme-starbucks-dna button { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 600; }
.theme-starbucks-dna h2::before { content: "☕ "; font-size: 0.7em; vertical-align: middle; }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
